def min_Jumps(steps, d):
    (a, b) = steps
    temp = a
    a = min(a, b)
    b = max(temp, b)
    if d == 0:
        return 0.0
    if d == a:
        return 1.0
    if d % b == 0:
        return float(d // b)
    if d < b:
        return 2.0
    return (d / b) + (d % b != 0) * (a / b)

